<h1 class="h3 mb-4">Histórico</h1><h2 class="h5">Vídeos gerados</h2><div class="table-responsive mb-4"><table class="table table-bordered bg-white"><thead><tr><th>Assunto</th><th>Título</th><th>Status</th><th>Gerado em</th><th>Erro</th></tr></thead><tbody><?php foreach ($videos as $video): ?><tr><td><?= htmlspecialchars($video['assunto'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($video['titulo_gerado'] ?? '—', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($video['status'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($video['gerado_em'] ?? $video['criado_em'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($video['erro'] ?? '—', ENT_QUOTES, 'UTF-8') ?></td></tr><?php endforeach; ?><?php if (!$videos): ?><tr><td colspan="5" class="text-center text-muted">Nenhum vídeo encontrado.</td></tr><?php endif; ?></tbody></table></div><h2 class="h5">Publicações</h2><div class="table-responsive mb-4"><table class="table table-bordered bg-white"><thead><tr><th>Vídeo</th><th>Canal</th><th>Plataforma</th><th>Status</th><th>Agendada para</th><th>Erro</th></tr></thead><tbody><?php foreach ($publications as $publication): ?><tr><td><?= htmlspecialchars($publication['titulo_gerado'] ?? '—', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($publication['canal'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($publication['plataforma'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($publication['status'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($publication['agendado_para'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($publication['ultimo_erro'] ?? '—', ENT_QUOTES, 'UTF-8') ?></td></tr><?php endforeach; ?><?php if (!$publications): ?><tr><td colspan="6" class="text-center text-muted">Nenhuma publicação encontrada.</td></tr><?php endif; ?></tbody></table></div><h2 class="h5">Execuções</h2><div class="table-responsive"><table class="table table-bordered bg-white"><thead><tr><th>Tipo</th><th>Status</th><th>Início</th><th>Fim</th><th>Erro</th></tr></thead><tbody><?php foreach ($executions as $execution): ?><tr><td><?= htmlspecialchars($execution['tipo'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($execution['status'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($execution['iniciado_em'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($execution['encerrado_em'] ?? '—', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($execution['mensagem_erro'] ?? '—', ENT_QUOTES, 'UTF-8') ?></td></tr><?php endforeach; ?><?php if (!$executions): ?><tr><td colspan="5" class="text-center text-muted">Nenhuma execução encontrada.</td></tr><?php endif; ?></tbody></table></div><a class="d-block mt-3" href="/dashboard">Voltar ao dashboard</a>
